// One audio graph for the page and its camera iframe. Original recordings stay local to the site.
(()=>{
  const CONFIG={master:.72,fanNormal:.14,fanCreepyDry:.11,fanHarsh:.035,noise:.008,typingGain:.48};
  const files={fan:'audio/fan-corrected.mp3',bling:'audio/bling.mp3',keyboard:'audio/typing-word.mp3'},raw={},buffers={},pending={};
  let ctx,master,fan=null,bling=null,facecam=false,raised=false,portalMix=0,handPortalMix=0,gradientOpen=false,typingToken=0,voices=new Set(),blingToken=0;
  const downloads=Object.fromEntries(Object.entries(files).map(([key,url])=>[key,fetch(url).then(r=>{if(!r.ok)throw Error('Audio unavailable');return r.arrayBuffer()}).then(b=>raw[key]=b).catch(()=>null)]));
  function ramp(param,value,time=.18){param.cancelScheduledValues(ctx.currentTime);param.setTargetAtTime(value,ctx.currentTime,time/3)}
  function init(){if(!ctx){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return false;ctx=new Audio();master=ctx.createGain();master.gain.value=CONFIG.master;const limiter=ctx.createDynamicsCompressor();limiter.threshold.value=-5;limiter.knee.value=3;limiter.ratio.value=16;limiter.attack.value=.003;limiter.release.value=.12;master.connect(limiter);limiter.connect(ctx.destination)}if(ctx.state==='suspended')ctx.resume().catch(()=>{});return true}
  async function buffer(key){if(!init())return null;if(buffers[key])return buffers[key];if(!pending[key])pending[key]=downloads[key].then(()=>raw[key]?ctx.decodeAudioData(raw[key].slice(0)):null).then(b=>buffers[key]=b).catch(()=>null);return pending[key]}
  function stopOne(sound){if(!sound||!ctx)return;ramp(sound.gain.gain,0,.06);try{sound.source.stop(ctx.currentTime+.08)}catch{}setTimeout(()=>{sound.source.disconnect();sound.gain.disconnect()},120)}
  async function startFan(){const b=await buffer('fan');if(!b||!facecam||document.hidden||fan)return;const source=ctx.createBufferSource(),dry=ctx.createGain(),pre=ctx.createGain(),distortion=ctx.createWaveShaper(),wet=ctx.createGain(),noise=ctx.createBufferSource(),noiseGain=ctx.createGain(),filter=ctx.createBiquadFilter(),bus=ctx.createGain();source.buffer=b;source.loop=true;pre.gain.value=.8;const curve=new Float32Array(4096);for(let i=0;i<curve.length;i++)curve[i]=Math.tanh((i/(curve.length-1)*2-1)*2.2);distortion.curve=curve;distortion.oversample='2x';
    const grain=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=grain.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;noise.buffer=grain;noise.loop=true;filter.type='bandpass';filter.frequency.value=650;filter.Q.value=.55;
    source.connect(dry);dry.connect(bus);source.connect(pre);pre.connect(distortion);distortion.connect(wet);wet.connect(bus);noise.connect(filter);filter.connect(noiseGain);noiseGain.connect(bus);bus.connect(master);bus.gain.value=0;dry.gain.value=CONFIG.fanCreepyDry+(CONFIG.fanNormal-CONFIG.fanCreepyDry)*portalMix;wet.gain.value=CONFIG.fanHarsh*(1-portalMix);noiseGain.gain.value=CONFIG.noise*(1-portalMix);fan={source,noise,dry,wet,noiseGain,bus,nodes:[source,noise,dry,pre,distortion,wet,filter,noiseGain,bus]};source.start();noise.start();ramp(bus.gain,1,.25);state();
  }
  function stopFan(){if(!fan)return;const old=fan;fan=null;ramp(old.bus.gain,0,.12);old.source.stop(ctx.currentTime+.14);old.noise.stop(ctx.currentTime+.14);setTimeout(()=>old.nodes.forEach(n=>n.disconnect()),180)}
  function state(){document.body.dataset.fanSound=facecam?(portalMix>=.99?'normal':portalMix>0?'transitioning':'creepy'):'off';document.body.dataset.soundReady=String(ctx?.state==='running')}
  function portal(value){const wasFull=portalMix===1;handPortalMix=Math.max(0,Math.min(1,value));const next=gradientOpen?1:handPortalMix;if(next===portalMix)return;portalMix=next;if(!wasFull&&next===1)playBling();if(fan){ramp(fan.dry.gain,CONFIG.fanCreepyDry+(CONFIG.fanNormal-CONFIG.fanCreepyDry)*portalMix,.6);ramp(fan.wet.gain,CONFIG.fanHarsh*(1-portalMix),.6);ramp(fan.noiseGain.gain,CONFIG.noise*(1-portalMix),.6)}state()}
  function gradient(value){gradientOpen=!!value;portal(handPortalMix)}
  function hand(value){raised=!!value;state()}
  function setFacecam(value){facecam=!!value;raised=false;handPortalMix=0;portalMix=gradientOpen?1:0;if(facecam){init();startFan()}else{stopFan();stopTyping()}state()}
  async function playBling(){const token=++blingToken,b=await buffer('bling');if(!b||token!==blingToken||document.hidden)return;stopOne(bling);const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=b;source.connect(gain);gain.connect(master);const now=ctx.currentTime,duration=b.duration;gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(.85,now+.012);gain.gain.setValueAtTime(.85,now+duration-.08);gain.gain.linearRampToValueAtTime(0,now+duration);source.start(now,0,duration);bling={source,gain};source.onended=()=>{source.disconnect();gain.disconnect();if(bling?.source===source)bling=null};document.body.dataset.lastSound='bling'}
  async function word(){const token=typingToken,b=await buffer('keyboard');if(!b||ctx.state!=='running'||token!==typingToken||document.hidden)return;const profile=Math.floor(Math.random()*3),count=1+Math.floor(Math.random()*3),base=.84+Math.random()*.36;for(let i=0;i<count;i++){const source=ctx.createBufferSource(),gain=ctx.createGain(),filter=ctx.createBiquadFilter(),pan=ctx.createStereoPanner?.();source.buffer=b;source.playbackRate.value=base+(Math.random()-.5)*.15;filter.type=['lowpass','bandpass','highpass'][profile];filter.frequency.value=[2600,1900,700][profile]*(.8+Math.random()*.5);filter.Q.value=profile===1?.75:.5;source.connect(filter);filter.connect(gain);if(pan){pan.pan.value=(Math.random()-.5)*.3;gain.connect(pan);pan.connect(master)}else gain.connect(master);const when=ctx.currentTime+i*(.025+Math.random()*.025),duration=b.duration/source.playbackRate.value;gain.gain.setValueAtTime(0,when);gain.gain.linearRampToValueAtTime(CONFIG.typingGain*(.65+Math.random()*.35)/(i?1.7:1),when+.003);gain.gain.exponentialRampToValueAtTime(.001,when+Math.max(.012,duration));const voice={source,gain};voices.add(voice);source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect();pan?.disconnect();voices.delete(voice)};source.start(when);if(voices.size>18){const oldest=voices.values().next().value;stopOne(oldest);voices.delete(oldest)}}document.body.dataset.lastSound='typing-word';document.body.dataset.typingHits=String(Number(document.body.dataset.typingHits||0)+1)}
  function stopTyping(){typingToken++;for(const voice of voices)stopOne(voice);voices.clear()}
  window.siteSound={setFacecam,hand,portal,gradient,word,stopTyping,CONFIG};
  function unlock(){if(init())for(const key of Object.keys(files))buffer(key);if(facecam)startFan();state()}addEventListener('pointerdown',unlock,{capture:true});addEventListener('keydown',unlock,{capture:true});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){stopFan();stopTyping();blingToken++;stopOne(bling);bling=null}else if(facecam)startFan()});
  addEventListener('pagehide',()=>{facecam=false;stopFan();stopTyping();blingToken++;stopOne(bling);ctx?.close()});state();
})();
